using System.Reflection;using System.Text.Json;
namespace RisingLands;
public static class CombatDiplomacyTests {
 public static void Run(string root,string output){int checks=0;void Check(bool ok,string text){if(!ok)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}void Invoke(Simulation s,string method,params object[] args)=>typeof(Simulation).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(s,args);
 var s=TradeV97Tests.Fixture(root);var a=s.World.Units.First(a=>a.Owner==0&&a.Type==0&&VisualCatalog.Visible(a));var b=s.World.Units.First(a=>a.Owner==1&&VisualCatalog.Visible(a));s.Campaign.Goodwill[1]=20;
 Check(s.Attack(a,b)&&s.Goodwill(1)==20,"hostile order alone is not a landed hit");a.AttackTarget=-1;Invoke(s,"ApplyHit",a,b,1);Check(s.Goodwill(1)==20,"landed hostile unit damage preserves goodwill");Invoke(s,"ApplyHit",a,b,0);Check(s.Goodwill(1)==20,"zero damage does not penalize");Invoke(s,"ApplyHit",b,a,1);Check(s.Goodwill(1)==20,"enemy attack changes no enemy opinion of player");s.Campaign.Goodwill[1]=-49;Invoke(s,"ApplyHit",a,b,1);Check(s.Goodwill(1)==-49,"hostile hit preserves negative goodwill");
 s.Campaign.Goodwill[1]=50;s.Campaign.Alliances[1]=true;Check(s.Attack(a,b)&&!s.Allied(1)&&s.Goodwill(1)==15,"ally attack costs35 and breaks alliance");Check(s.Attack(a,b)&&s.Goodwill(1)==15,"repeated order cannot repeat betrayal");a.AttackTarget=-1;Invoke(s,"ApplyHit",a,b,1);Check(s.Goodwill(1)==15,"subsequent hostile hit has no additional penalty");
 var building=s.World.Buildings.First(x=>x.Owner==1);s.Campaign.Goodwill[1]=50;s.Campaign.Alliances[1]=true;Check(s.AttackBuilding(a,building.Slot)&&s.Goodwill(1)==15&&!s.Allied(1),"ally structure order breaks alliance and costs35");s.Opponent.Sieges.Clear();s.Campaign.Goodwill=new[]{0,50,20,-10};Invoke(s,"HitStructure",building,10,0);Check(s.Goodwill(1)==50&&s.Goodwill(2)==20&&s.Goodwill(3)==-10,"hostile structure damage preserves all clans opinions");var values=(int[])s.Campaign.Goodwill.Clone();Invoke(s,"HitStructure",building,0,0);Check(s.Campaign.Goodwill.SequenceEqual(values),"zero structure damage no event");Invoke(s,"HitStructure",building,1,-1);Check(s.Campaign.Goodwill.SequenceEqual(values),"research damage without attacker no event");
 var copy=TradeV97Tests.Fixture(root);string save=s.Serialize();copy.Restore(save);Check(copy.Serialize()==save&&copy.Campaign.Goodwill.SequenceEqual(values),"diplomacy save/load unchanged format");
 s=TradeV97Tests.Fixture(root);a=s.World.Units.First(x=>x.Owner==0&&x.Type==0&&VisualCatalog.Visible(x));b=s.World.Units.First(x=>x.Owner==1&&VisualCatalog.Visible(x));b.X=a.X+1024;b.Y=a.Y;s.Attack(a,b);int health=b.Health;for(int i=0;i<300&&b.Health==health;i++)s.Step();Check(b.Health<health&&s.Goodwill(1)==0,"real combat deals damage without changing sympathy");
 File.WriteAllText(output,JsonSerializer.Serialize(new{Checks=checks,Passed=true}));
 }
}
